BEGIN;
-- Past GCE and regional mock questions, extracted from the school's
-- 334-page pamphlet. Generated by tools/load_questions.py — do not edit
-- this file by hand; correct the extract and regenerate.
--
-- Requires db/phase5.sql to have been run first.
--
-- 408 multiple choice, 114 structured.
-- 128 arrive ready to use; 394 are marked needs_review.
-- Nothing is auto_markable on import. A question starts marking itself
-- only after a teacher has checked it against the source page.

-- Refuse to run if phase5 is missing, rather than failing halfway
-- through with a column error and leaving a partial bank behind.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                 WHERE table_name = 'questions' AND column_name = 'needs_review')
  THEN
    RAISE EXCEPTION 'Run db/phase5.sql before this seed.';
  END IF;
END $$;

-- The syllabus is found by name, not by a hardcoded id. Two databases
-- built from the same seed files can hold different ids for the same
-- syllabus, and a seed that assumes one of them is useless on the other.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM syllabi
                 WHERE form_level = 'Form 5' AND deleted_at IS NULL)
  THEN
    RAISE EXCEPTION 'No Form 5 syllabus found. Run the curriculum seeds in db/seed/ first (01, then 02, then 03).';
  END IF;
END $$;

