CROSS JOIN (
  SELECT id FROM syllabi
  WHERE form_level = 'Form 5' AND deleted_at IS NULL
  ORDER BY created_at LIMIT 1
) AS target
ON CONFLICT (id) DO NOTHING;

-- --------------------------------------------------------------------
-- 1611 options
--
-- Deleted and rewritten rather than upserted: options have generated
-- ids, so there is nothing stable to conflict on, and they are always
-- replaced as a set. Only rows from this batch are touched.
-- --------------------------------------------------------------------

DELETE FROM question_options WHERE question_id IN (
  SELECT id FROM questions WHERE import_batch = 'gce-pamphlet-2026'
);

;

COMMIT;

-- What arrived, and how much of it still needs a human.
SELECT question_type,
       count(*) AS loaded,
       count(*) FILTER (WHERE needs_review) AS needs_review
FROM questions WHERE import_batch = 'gce-pamphlet-2026' AND deleted_at IS NULL
GROUP BY question_type ORDER BY question_type;
